    23	  | { readonly kind: "materialize_stage"; readonly stage_key: StageKey; readonly stage_instance_id: StageInstanceId; readonly policy: StagePolicy }
    24	  | {
    25	      readonly kind: "materialize_unit";
    26	      readonly stage_key: StageKey;
    27	      readonly stage_instance_id: StageInstanceId;
    28	      readonly run_unit_id: ExecutionUnitId;
    29	      readonly unit_id: UnitId;
    30	      readonly parameters: JsonValue;
