    33	      readonly input_snapshot: readonly ArtifactEnvelope[];
    34	      readonly input_fingerprint: InputFingerprint;
    35	      readonly outputs: readonly MaterializedRunOutput[];
    36	      /** Part of the stage's stored materialization fingerprint; `apply` needs it to persist the unit. */
    37	      readonly policy: StagePolicy;
