    50	  | { readonly kind: "close_materialization"; readonly stage_key: StageKey; readonly stage_instance_id: StageInstanceId; readonly policy: StagePolicy }
    51	  | { readonly kind: "mark_unit_satisfied"; readonly run_unit_id: ExecutionUnitId }
    52	  | { readonly kind: "start_work"; readonly work_order_id: WorkOrderId; readonly run_unit_id: ExecutionUnitId }
    53	  | { readonly kind: "mark_stage_succeeded"; readonly stage_instance_id: StageInstanceId }
    54	  | { readonly kind: "complete_run"; readonly outcome: StageOutcome };
    55	
    56	export type Contradiction =
    57	  | { readonly kind: "unknown_dependency_at_close"; readonly stage_key: StageKey; readonly unit_id: UnitId; readonly dependency: UnitId }
    58	  | { readonly kind: "dependency_cycle"; readonly stage_key: StageKey; readonly cycle: readonly UnitId[] }
    59	  /** `artifact_id` is null only when the fan-out drives over a non-input binding (repository provisioning fans out over run context). */
    60	  | { readonly kind: "malformed_driver_artifact"; readonly stage_key: StageKey; readonly artifact_id: ArtifactId | null; readonly path: string; readonly detail: string };
