     1	export type Brand<Value, Name extends string> = Value & { readonly __brand: Name };
     2	
     3	const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
     4	
     5	/**
     6	 * Parse a path segment into a uuid-shaped branded id, or nothing.
     7	 *
     8	 * These ids are stored in `uuid` columns, so a malformed one is not a lookup
     9	 * that finds nothing — Postgres rejects the value while casting it, and the
    10	 * route answers 500 for what is simply an id that cannot exist. The brand is
    11	 * the caller's to name, exactly as the bare `as` casts this replaces did, but
    12	 * now the value has been checked before it carries the name.
    13	 *
    14	 * `UnitId` and `ExecutionId` are deliberately not covered: both are text
    15	 * columns, so any string is a legitimate lookup that finds nothing.
    16	 */
    17	export const parseUuidId = <Id extends string>(raw: string | undefined): Id | null =>
    18	  raw !== undefined && UUID_PATTERN.test(raw) ? raw as Id : null;
    19	
    20	export type WorkflowDefinitionId = Brand<string, "WorkflowDefinitionId">;
    21	export type WorkflowRunId = Brand<string, "WorkflowRunId">;
