    29	export type WaitId = Brand<string, "WaitId">;
    30	export type ExecutionUnitId = Brand<string, "ExecutionUnitId">;
    31	export type WorkOrderId = Brand<string, "WorkOrderId">;
    32	export type ExecutorOperationId = Brand<string, "ExecutorOperationId">;
    33	export type RunRecordVersion = Brand<number, "RunRecordVersion">;
    34	export type OutputSlotVersion = Brand<number, "OutputSlotVersion">;
    35	export type OutputCollectionKey = Brand<string, "OutputCollectionKey">;
    36	export type InputFingerprint = Brand<string, "InputFingerprint">;
    37	export type RunTransitionId = Brand<string, "RunTransitionId">;
    38	
    39	/**
    40	 * One attempt at an execution — the ID of the workflow running it. A rerun
    41	 * forks that workflow under a new ID, so this changes per attempt while staying
    42	 * stable across step retries and recovery of the same attempt. That is exactly
    43	 * the identity an external executor session must be keyed on: the execution id
    44	 * alone is shared by every attempt, so keying on it makes a rerun re-attach to
    45	 * the session that already died.
    46	 */
    47	export type ExecutionAttemptId = Brand<string, "ExecutionAttemptId">;
    48	
    49	export const executorOperationIdForWorkOrder = (id: WorkOrderId): ExecutorOperationId => id as unknown as ExecutorOperationId;
    50	
    51	export type JsonPrimitive = string | number | boolean | null;
    52	export type JsonValue = JsonPrimitive | readonly JsonValue[] | { readonly [key: string]: JsonValue };
    53	
    54	/** Narrows parsed request bodies at the IO boundary; lives beside the type it guards. */
    55	export const isJsonValue = (value: unknown): value is JsonValue => {
    56	  if (value === null || typeof value === "string" || typeof value === "number" || typeof value === "boolean") return true;
    57	  if (Array.isArray(value)) return value.every(isJsonValue);
    58	  return typeof value === "object" && Object.values(value as object).every(isJsonValue);
    59	};
    60	
    61	export type Result<Value, ErrorValue> =
    62	  | { readonly ok: true; readonly value: Value }
    63	  | { readonly ok: false; readonly error: ErrorValue };
    64	
    65	export const ok = <Value>(value: Value): Result<Value, never> => ({ ok: true, value });
    66	export const err = <ErrorValue>(error: ErrorValue): Result<never, ErrorValue> => ({ ok: false, error });

